def clear_thoughts(mode=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sanitize_payload():
        return {"mode": mode} if mode is not None else {}

    t0 = time.time()
    tool_name = "clear_thoughts"

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    resets = _load("session_resets.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    api_key = None
    if api_keys:
        # Ambient auth: choose any active key that can serve requests (rate_limit exists by schema).
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break

    def _count_recent_requests_for_key(key_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in reqlog:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and dt <= now_dt and r.get("status") in ("success", "error", "rate_limited"):
                c += 1
        return c

    def _log(status, session_id=None, response_meta=None):
        dt_now = _now()
        duration_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key.get("id") if isinstance(api_key, dict) else None,
            "session_id": session_id,
            "tool_name": tool_name,
            "status": status,
            "request_payload": _sanitize_payload(),
            "response_meta": response_meta or {},
            "duration_ms": duration_ms,
            "created_at": dt_now,
            "updated_at": dt_now,
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    # Validate
    if mode is None:
        mode = "soft"
    if not isinstance(mode, str) or mode not in ("soft", "hard"):
        _log("error", None, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "mode must be one of 'soft' or 'hard'")

    # Resolve current session context (ambient): prefer active, else cleared (non-archived)
    current_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "cleared"):
            current_session = s
            break
    if current_session is None:
        _log("error", None, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active session context")

    # Rate limit (only enforced when api_key exists per business rule)
    if isinstance(api_key, dict):
        try:
            rpm = int(api_key.get("rate_limit_rpm"))
        except Exception:
            rpm = None
        if rpm is not None:
            now_dt = datetime.datetime.utcnow()
            used = _count_recent_requests_for_key(api_key.get("id"), now_dt)
            if used >= rpm:
                _log("rate_limited", current_session.get("id"), {"rate_limit_rpm": rpm, "used_last_minute": used})
                return _err("RATE_LIMIT", "Rate limit exceeded")

    # Ensure session exists (NOT_FOUND if referenced but missing - here we have a row)
    sid = current_session.get("id")
    if not isinstance(sid, str) or not sid:
        _log("error", None, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session does not exist")

    # Session clearability: archived not allowed; lifecycle allows active->cleared, cleared->cleared? (not allowed).
    if current_session.get("status") == "archived":
        _log("error", sid, {"error_code": "CONFLICT"})
        return _err("CONFLICT", "Session is not clearable in archived status")
    if current_session.get("status") == "cleared":
        # idempotent-ish: allow clearing again but must still have effect.
        # If no recorded thoughts remain, then no effect => NOT_FOUND per mutation rule? Better CONFLICT: already cleared.
        any_recorded = any(isinstance(t, dict) and t.get("session_id") == sid and t.get("status") == "recorded" for t in thoughts)
        if not any_recorded and mode == "soft":
            _log("error", sid, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "Session is already cleared")

    now = _now()

    # Gather thoughts for session
    sess_thoughts_idx = [i for i, t in enumerate(thoughts) if isinstance(t, dict) and t.get("session_id") == sid]
    sess_recorded_idx = [i for i in sess_thoughts_idx if thoughts[i].get("status") == "recorded"]
    cleared_count = 0
    cleared_chars = 0

    if mode == "hard":
        if not sess_thoughts_idx:
            _log("error", sid, {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No thoughts found to clear")
        # Hard delete all thoughts for the session
        for i in reversed(sess_thoughts_idx):
            t = thoughts[i]
            if isinstance(t, dict) and isinstance(t.get("thought_chars"), int) and t.get("status") != "deleted":
                cleared_chars += t.get("thought_chars", 0)
                cleared_count += 1
            elif isinstance(t, dict) and t.get("status") == "deleted" and isinstance(t.get("thought_chars"), int):
                # for hard delete, count all removed rows? keep cleared_count definition as number of rows removed
                pass
            thoughts.pop(i)
        # Update session to cleared (only if transition legal)
        if current_session.get("status") == "active":
            current_session["status"] = "cleared"
        elif current_session.get("status") == "cleared":
            # remain cleared
            pass
        else:
            _log("error", sid, {"error_code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Cannot clear session from current status")
        current_session["cleared_at"] = now
        current_session["thought_count"] = 0
        current_session["total_chars"] = 0
        current_session["last_thought_at"] = None
        current_session["updated_at"] = now

        # Create reset row
        reset_row = {
            "id": _new_id("reset"),
            "session_id": sid,
            "status": "applied",
            "cleared_thoughts_count": int(cleared_count),
            "cleared_total_chars": int(cleared_chars),
            "created_at": now,
            "updated_at": now,
        }
        resets.append(reset_row)

        _save("thoughts.json", thoughts)
        _save("sessions.json", sessions)
        _save("session_resets.json", resets)

        _log("success", sid, {"mode": mode, "cleared_thoughts_count": cleared_count, "cleared_total_chars": cleared_chars})
        return {
            "session_id": sid,
            "mode": mode,
            "reset": reset_row,
            "cleared_thoughts_count": cleared_count,
            "cleared_total_chars": cleared_chars,
            "session": {
                "id": current_session.get("id"),
                "status": current_session.get("status"),
                "thought_count": current_session.get("thought_count"),
                "total_chars": current_session.get("total_chars"),
                "last_thought_at": current_session.get("last_thought_at"),
                "cleared_at": current_session.get("cleared_at"),
                "updated_at": current_session.get("updated_at"),
            },
        }

    # soft
    if not sess_recorded_idx:
        _log("error", sid, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No recorded thoughts found to clear")

    # Soft delete only recorded thoughts
    for i in sess_recorded_idx:
        t = thoughts[i]
        if t.get("status") != "recorded":
            continue
        t["status"] = "deleted"
        t["deleted_at"] = now
        t["updated_at"] = now
        cleared_count += 1
        if isinstance(t.get("thought_chars"), int):
            cleared_chars += t.get("thought_chars", 0)

    # Update session to cleared respecting transitions
    if current_session.get("status") == "active":
        current_session["status"] = "cleared"
    elif current_session.get("status") == "cleared":
        # keep cleared
        pass
    else:
        _log("error", sid, {"error_code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Cannot clear session from current status")

    current_session["cleared_at"] = now
    current_session["thought_count"] = 0
    current_session["total_chars"] = 0
    current_session["last_thought_at"] = None
    current_session["updated_at"] = now

    reset_row = {
        "id": _new_id("reset"),
        "session_id": sid,
        "status": "applied",
        "cleared_thoughts_count": int(cleared_count),
        "cleared_total_chars": int(cleared_chars),
        "created_at": now,
        "updated_at": now,
    }
    resets.append(reset_row)

    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)
    _save("session_resets.json", resets)

    _log("success", sid, {"mode": mode, "cleared_thoughts_count": cleared_count, "cleared_total_chars": cleared_chars})
    return {
        "session_id": sid,
        "mode": mode,
        "reset": reset_row,
        "cleared_thoughts_count": cleared_count,
        "cleared_total_chars": cleared_chars,
        "session": {
            "id": current_session.get("id"),
            "status": current_session.get("status"),
            "thought_count": current_session.get("thought_count"),
            "total_chars": current_session.get("total_chars"),
            "last_thought_at": current_session.get("last_thought_at"),
            "cleared_at": current_session.get("cleared_at"),
            "updated_at": current_session.get("updated_at"),
        },
    }

def get_thought_stats(include_deleted=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    tool_name = "get_thought_stats"

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    api_key = None
    if api_keys:
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break

    def _count_recent_requests_for_key(key_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in reqlog:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and dt <= now_dt and r.get("status") in ("success", "error", "rate_limited"):
                c += 1
        return c

    def _log(status, session_id=None, response_meta=None):
        dt_now = _now()
        duration_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key.get("id") if isinstance(api_key, dict) else None,
            "session_id": session_id,
            "tool_name": tool_name,
            "status": status,
            "request_payload": {"include_deleted": include_deleted} if include_deleted is not None else {},
            "response_meta": response_meta or {},
            "duration_ms": duration_ms,
            "created_at": dt_now,
            "updated_at": dt_now,
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", None, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean")

    current_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "cleared"):
            current_session = s
            break
    if current_session is None:
        _log("error", None, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active session context")

    # Rate limit per key if present
    if isinstance(api_key, dict):
        try:
            rpm = int(api_key.get("rate_limit_rpm"))
        except Exception:
            rpm = None
        if rpm is not None:
            now_dt = datetime.datetime.utcnow()
            used = _count_recent_requests_for_key(api_key.get("id"), now_dt)
            if used >= rpm:
                _log("rate_limited", current_session.get("id"), {"rate_limit_rpm": rpm, "used_last_minute": used})
                return _err("RATE_LIMIT", "Rate limit exceeded")

    sid = current_session.get("id")
    if not isinstance(sid, str) or not sid:
        _log("error", None, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session does not exist")

    # Compute from thoughts for consistency
    filtered = []
    for t in thoughts:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != sid:
            continue
        if not include_deleted and t.get("status") == "deleted":
            continue
        if t.get("status") not in ("recorded", "deleted"):
            continue
        filtered.append(t)

    count = 0
    total_chars = 0
    last_thought_at = None
    last_seq = None
    for t in filtered:
        if not include_deleted and t.get("status") != "recorded":
            continue
        if include_deleted and t.get("status") not in ("recorded", "deleted"):
            continue
        count += 1
        if isinstance(t.get("thought_chars"), int):
            total_chars += t.get("thought_chars", 0)
        seq = t.get("sequence")
        if isinstance(seq, int):
            if last_seq is None or seq > last_seq:
                last_seq = seq
                last_thought_at = t.get("created_at")

    # If include_deleted=False, align with session cached fields if session is consistent; we still return computed.
    resp = {
        "session_id": sid,
        "include_deleted": include_deleted,
        "count": int(count),
        "total_chars": int(total_chars),
        "last_thought_at": last_thought_at,
        "session_cached": {
            "thought_count": current_session.get("thought_count"),
            "total_chars": current_session.get("total_chars"),
            "last_thought_at": current_session.get("last_thought_at"),
            "status": current_session.get("status"),
        },
    }
    _log("success", sid, {"count": count, "total_chars": total_chars})
    return resp

def get_thoughts(include_deleted=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dur_ms():
        ms = int((time.perf_counter() - t0) * 1000)
        if ms < 0:
            ms = 0
        if ms > 600000:
            ms = 600000
        return ms

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        s = x[:-1] if x.endswith("Z") else x
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _pick_current_session(sessions, thoughts):
        # Prefer sessions that actually have any thoughts (including deleted),
        # then most recently updated/created. Must be non-archived.
        sess = [s for s in sessions if isinstance(s, dict) and s.get("status") in ("active", "cleared")]
        if not sess:
            return None
        thought_sids = set()
        for t in thoughts:
            if isinstance(t, dict) and isinstance(t.get("session_id"), str):
                thought_sids.add(t.get("session_id"))
        def _key(s):
            sid = s.get("id")
            has_any = 1 if sid in thought_sids else 0
            return (
                has_any,
                1 if s.get("status") == "active" else 0,
                _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min
            )
        sess.sort(key=_key, reverse=True)
        return sess[0]

    def _log(reqlog, api_key_id, session_id, status, request_payload, response_meta):
        row = {
            "id": _new_id("tt_req"),
            "api_key_id": api_key_id,
            "session_id": session_id,
            "tool_name": "get_thoughts",
            "status": status,
            "request_payload": request_payload,
            "response_meta": response_meta,
            "duration_ms": _dur_ms(),
            "created_at": now,
            "updated_at": now,
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    def _enforce_rate_limit(api_key, reqlog):
        # Per business rules: enforce per api_keys.rate_limit_rpm using request_log timestamps.
        if not api_key or api_key.get("status") != "active":
            return True, None
        rpm = api_key.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            # If store is inconsistent, don't brick calls; treat as no limit.
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        count = 0
        for r in reqlog:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                count += 1
        if count >= rpm:
            return False, rpm
        return True, rpm

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    # Ambient auth: choose any active key for rate-limiting context if present; otherwise proceed unauthenticated.
    api_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            api_key = k
            break
    api_key_id = api_key.get("id") if api_key else None

    session = _pick_current_session(sessions, thoughts)
    session_id = session.get("id") if session else None
    if session is None:
        _log(reqlog, api_key_id, None, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active session context is available for the caller.")

    # Rate limit (even reads)
    allowed, rpm = _enforce_rate_limit(api_key, reqlog)
    if not allowed:
        _log(reqlog, api_key_id, session_id, "rate_limited", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "RATE_LIMIT", "rate_limit_rpm": rpm})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_rpm=rpm)

    # Validate inputs
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean if provided.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if sort is None:
        sort = "sequence_asc"
    if sort not in ("sequence_asc", "sequence_desc"):
        _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort value; must be 'sequence_asc' or 'sequence_desc'.")

    # Cursor format: accept "seq:<int>" (legacy) as used by callers; also accept empty/None.
    cursor_seq = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) == 0:
            _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if cursor.startswith("seq:"):
            n = cursor[4:]
            try:
                cursor_seq = int(n)
            except ValueError:
                _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if cursor_seq < 0:
                _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        else:
            _log(reqlog, api_key_id, session_id, "error", {"include_deleted": include_deleted, "limit": limit, "cursor": cursor, "sort": sort}, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    inc_del = bool(include_deleted) if include_deleted is not None else False
    sess_thoughts = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == session_id]
    if not inc_del:
        sess_thoughts = [t for t in sess_thoughts if t.get("status") != "deleted"]

    # Sort and paginate by sequence
    def _seq(t):
        v = t.get("sequence")
        return v if isinstance(v, int) else 0

    reverse = (sort == "sequence_desc")
    sess_thoughts.sort(key=_seq, reverse=reverse)

    if cursor_seq is not None:
        if reverse:
            sess_thoughts = [t for t in sess_thoughts if _seq(t) < cursor_seq]
        else:
            sess_thoughts = [t for t in sess_thoughts if _seq(t) > cursor_seq]

    page = sess_thoughts[:limit]
    has_more = len(sess_thoughts) > limit
    next_cursor = None
    if page and has_more:
        last_seq = _seq(page[-1])
        next_cursor = f"seq:{last_seq}"

    # Response rows: return as stored (no fabrication), but exclude nothing beyond requested filter.
    resp = {
        "session_id": session_id,
        "thoughts": page,
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total_returned": len(page),
    }
