def think(thought, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    tool_name = "think"

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    api_key = None
    if api_keys:
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break

    def _count_recent_requests_for_key(key_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in reqlog:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and dt <= now_dt and r.get("status") in ("success", "error", "rate_limited"):
                c += 1
        return c

    def _log(status, session_id=None, response_meta=None, error_code=None):
        dt_now = _now()
        duration_ms = int(max(0, (time.time() - t0) * 1000))
        payload = {"thought": "[redacted]", "thought_chars": len(thought) if isinstance(thought, str) else None}
        meta = response_meta or {}
        if error_code:
            meta = dict(meta)
            meta["error_code"] = error_code
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key.get("id") if isinstance(api_key, dict) else None,
            "session_id": session_id,
            "tool_name": tool_name,
            "status": status,
            "request_payload": payload,
            "response_meta": meta,
            "duration_ms": duration_ms,
            "created_at": dt_now,
            "updated_at": dt_now,
        }
        reqlog.append(row)
        _save("request_log.json", reqlog)

    # Validate thought
    if not isinstance(thought, str):
        _log("error", None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought must be a string")
    trimmed = thought.strip()
    if len(trimmed) == 0:
        _log("error", None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought must be a non-empty string")

    max_chars = 200000
    if isinstance(api_key, dict) and isinstance(api_key.get("max_thought_chars"), int):
        max_chars = int(api_key.get("max_thought_chars"))
    if len(thought) > max_chars:
        _log("error", None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"thought exceeds max_thought_chars ({max_chars})")

    # Rate limit per api key if present
    if isinstance(api_key, dict):
        try:
            rpm = int(api_key.get("rate_limit_rpm"))
        except Exception:
            rpm = None
        if rpm is not None:
            now_dt = datetime.datetime.utcnow()
            used = _count_recent_requests_for_key(api_key.get("id"), now_dt)
            if used >= rpm:
                _log("rate_limited", None, {"rate_limit_rpm": rpm, "used_last_minute": used})
                return _err("RATE_LIMIT", "Rate limit exceeded")

    now = _now()

    # Resolve or create current session.
    current_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "cleared"):
            current_session = s
            break

    if current_session is None:
        # Create new session (no client_key context available from params; leave null).
        sid = _new_id("sess")
        current_session = {
            "id": sid,
            "client_key": None,
            "status": "active",
            "cleared_at": None,
            "thought_count": 0,
            "total_chars": 0,
            "last_thought_at": None,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(current_session)
    else:
        sid = current_session.get("id")
        if not isinstance(sid, str) or not sid:
            _log("error", None, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Session does not exist")
        # If session is cleared, transition to active (legal) and continue sequences monotonically within session
        if current_session.get("status") == "cleared":
            current_session["status"] = "active"
            current_session["updated_at"] = now

    # Enforce max_session_thoughts if api_key present
    if isinstance(api_key, dict) and isinstance(api_key.get("max_session_thoughts"), int):
        max_thoughts = int(api_key.get("max_session_thoughts"))
        # Count non-deleted thoughts in session
        non_deleted = 0
        for t in thoughts:
            if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") == "recorded":
                non_deleted += 1
        if non_deleted >= max_thoughts:
            _log("error", sid, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Session has reached max_session_thoughts quota")

    # Determine next sequence: max(sequence) + 1 across all thoughts in session (including deleted)
    max_seq = 0
    for t in thoughts:
        if isinstance(t, dict) and t.get("session_id") == sid and isinstance(t.get("sequence"), int):
            if t["sequence"] > max_seq:
                max_seq = t["sequence"]
    next_seq = max_seq + 1

    # Enforce uniqueness(session_id, sequence) by construction; also ensure >=1
    if next_seq < 1:
        next_seq = 1

    # Insert thought row
    tid = _new_id("th")
    thought_chars = len(thought)
    if thought_chars > 200000:
        _log("error", sid, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought_chars exceeds 200000 hard limit")

    new_th = {
        "id": tid,
        "session_id": sid,
        "sequence": int(next_seq),
        "thought": thought,
        "thought_chars": int(thought_chars),
        "status": "recorded",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }
    thoughts.append(new_th)

    # Update session cached stats atomically (within this function)
    current_session["thought_count"] = int((current_session.get("thought_count") or 0) + 1)
    current_session["total_chars"] = int((current_session.get("total_chars") or 0) + thought_chars)
    current_session["last_thought_at"] = now
    current_session["updated_at"] = now
    if current_session["thought_count"] < 0 or current_session["total_chars"] < 0:
        _log("error", sid, error_code="CONFLICT")
        return _err("CONFLICT", "Session counters invalid")

    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)

    _log("success", sid, {"sequence": next_seq, "thought_chars": thought_chars})
    return {
        "session_id": sid,
        "thought": {
            "id": new_th["id"],
            "session_id": new_th["session_id"],
            "sequence": new_th["sequence"],
            "thought": new_th["thought"],
            "thought_chars": new_th["thought_chars"],
            "status": new_th["status"],
            "created_at": new_th["created_at"],
            "updated_at": new_th["updated_at"],
        },
        "session": {
            "id": current_session.get("id"),
            "status": current_session.get("status"),
            "thought_count": current_session.get("thought_count"),
            "total_chars": current_session.get("total_chars"),
            "last_thought_at": current_session.get("last_thought_at"),
            "updated_at": current_session.get("updated_at"),
        },
    }

def delete_thought(thought_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _dur_ms():
        ms = int((time.perf_counter() - t0) * 1000)
        if ms < 0:
            ms = 0
        if ms > 600000:
            ms = 600000
        return ms

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(x):
        if not isinstance(x, str) or not x:
            return None
        s = x[:-1] if x.endswith("Z") else x
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(reqlog_rows, api_key_id, session_id, status, request_payload, response_meta):
        reqlog_rows.append(
            {
                "id": _new_id("tt_req"),
                "api_key_id": api_key_id,
                "session_id": session_id,
                "tool_name": "delete_thought",
                "status": status,
                "request_payload": request_payload,
                "response_meta": response_meta,
                "duration_ms": _dur_ms(),
                "created_at": now,
                "updated_at": now,
            }
        )

    # Validate input
    if not isinstance(thought_id, str) or len(thought_id) < 1:
        reqlog = _load("request_log.json")
        _log(reqlog, None, None, "error", {"thought_id": thought_id}, {"error_code": "VALIDATION_ERROR"})
        _save("request_log.json", reqlog)
        return _err("VALIDATION_ERROR", "thought_id must be a non-empty string.")

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    # Resolve caller context: since no credential param is provided, choose a viable active api_key if any.
    # Rate limit is enforced only when an api_key is used.
    api_key = None
    for k in api_keys:
        if k.get("status") == "active" and isinstance(k.get("rate_limit_rpm"), int) and k.get("rate_limit_rpm", 0) >= 1:
            api_key = k
            break
    api_key_id = api_key.get("id") if api_key else None

    # Rate limit check (per api key if present)
    if api_key:
        rpm = api_key.get("rate_limit_rpm")
        try:
            rpm = int(rpm)
        except Exception:
            rpm = None
        if rpm is None or rpm < 1 or rpm > 6000:
            _log(reqlog, api_key_id, None, "error", {"thought_id": thought_id}, {"error_code": "VALIDATION_ERROR"})
            _save("request_log.json", reqlog)
            return _err("VALIDATION_ERROR", "API key has invalid rate_limit_rpm.")
        window_start = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in reqlog:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                used += 1
        if used >= rpm:
            _log(reqlog, api_key_id, None, "rate_limited", {"thought_id": thought_id}, {"limit_rpm": rpm, "used_in_window": used})
            _save("request_log.json", reqlog)
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit_rpm=rpm, used_in_window=used)

    # Find thought by id
    target_thought = None
    for t in thoughts:
        if t.get("id") == thought_id:
            target_thought = t
            break
    if target_thought is None:
        _log(reqlog, api_key_id, None, "error", {"thought_id": thought_id}, {"error_code": "NOT_FOUND"})
        _save("request_log.json", reqlog)
        return _err("NOT_FOUND", "No thought exists with that id.")

    session_id = target_thought.get("session_id")
    if not isinstance(session_id, str) or not session_id:
        _log(reqlog, api_key_id, None, "error", {"thought_id": thought_id}, {"error_code": "VALIDATION_ERROR"})
        _save("request_log.json", reqlog)
        return _err("VALIDATION_ERROR", "Thought row is missing a valid session_id.")

    # Determine "current session context": must have a non-archived session for the caller, and thought must belong to it.
    # With ambient auth, pick a non-archived session that matches the thought's session_id.
    current_session = None
    for s in sessions:
        if s.get("id") == session_id and s.get("status") in ("active", "cleared"):
            current_session = s
            break
    if current_session is None:
        # If the thought belongs to an archived session, there is no active session context for it.
        _log(reqlog, api_key_id, session_id, "error", {"thought_id": thought_id}, {"error_code": "UNAUTHORIZED"})
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No active session context for this thought (session is not active/cleared).")

    # Enforce lifecycle transition
    st = target_thought.get("status")
    if st == "deleted":
        _log(reqlog, api_key_id, session_id, "error", {"thought_id": thought_id}, {"error_code": "CONFLICT"})
        _save("request_log.json", reqlog)
        return _err("CONFLICT", "Thought is already deleted and cannot transition further.")
    if st != "recorded":
        _log(reqlog, api_key_id, session_id, "error", {"thought_id": thought_id}, {"error_code": "CONFLICT"})
        _save("request_log.json", reqlog)
        return _err("CONFLICT", f"Thought status '{st}' cannot transition to 'deleted'.")

    # Mutate thought (soft delete)
    target_thought["status"] = "deleted"
    target_thought["deleted_at"] = now
    target_thought["updated_at"] = now

    # Update cached session stats consistently
    # Decrement only if the thought was previously counted (recorded and not deleted).
    tc = target_thought.get("thought_chars")
    if not isinstance(tc, int):
        # fall back to length(thought)
        thtxt = target_thought.get("thought")
        tc = len(thtxt) if isinstance(thtxt, str) else 0

    if not isinstance(current_session.get("thought_count"), int):
        current_session["thought_count"] = 0
    if not isinstance(current_session.get("total_chars"), int):
        current_session["total_chars"] = 0

    current_session["thought_count"] = max(0, current_session["thought_count"] - 1)
    current_session["total_chars"] = max(0, current_session["total_chars"] - max(0, tc))

    # last_thought_at should be max created_at among non-deleted thoughts
    last_dt = None
    last_iso = None
    for t in thoughts:
        if t.get("session_id") != session_id:
            continue
        if t.get("status") == "deleted":
            continue
        cdt = _parse_dt(t.get("created_at"))
        if cdt is None:
            continue
        if last_dt is None or cdt > last_dt:
            last_dt = cdt
            last_iso = t.get("created_at")
    current_session["last_thought_at"] = last_iso
    current_session["updated_at"] = now

    # Persist
    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)

    _log(reqlog, api_key_id, session_id, "success", {"thought_id": thought_id}, {"deleted": 1})
    _save("request_log.json", reqlog)

    return {
        "thought": target_thought,
        "session": {
            "id": current_session.get("id"),
            "status": current_session.get("status"),
            "thought_count": current_session.get("thought_count"),
            "total_chars": current_session.get("total_chars"),
            "last_thought_at": current_session.get("last_thought_at"),
            "updated_at": current_session.get("updated_at"),
        },
    }

def rollback_clear(reset_id=None, **_extra):
