    t0 = time.perf_counter()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _dur_ms():
        ms = int((time.perf_counter() - t0) * 1000)
        if ms < 0:
            ms = 0
        if ms > 600000:
            ms = 600000
        return ms

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(x):
        if not isinstance(x, str) or not x:
            return None
        s = x[:-1] if x.endswith("Z") else x
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(reqlog_rows, api_key_id, session_id, status, request_payload, response_meta):
        reqlog_rows.append(
            {
                "id": _new_id("tt_req"),
                "api_key_id": api_key_id,
                "session_id": session_id,
                "tool_name": "rollback_clear",
                "status": status,
                "request_payload": request_payload,
                "response_meta": response_meta,
                "duration_ms": _dur_ms(),
                "created_at": now,
                "updated_at": now,
            }
        )

    # Validate input
    if reset_id is not None and (not isinstance(reset_id, str) or len(reset_id) < 1):
        reqlog = _load("request_log.json")
        _log(reqlog, None, None, "error", {"reset_id": reset_id}, {"error_code": "VALIDATION_ERROR"})
        _save("request_log.json", reqlog)
        return _err("VALIDATION_ERROR", "reset_id must be a non-empty string when provided.")

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    resets = _load("session_resets.json")
    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    # Resolve caller context: no explicit credential param; pick an active api_key if any.
    api_key = None
    for k in api_keys:
        if k.get("status") == "active" and isinstance(k.get("rate_limit_rpm"), int) and k.get("rate_limit_rpm", 0) >= 1:
            api_key = k
            break
    api_key_id = api_key.get("id") if api_key else None

    # Rate limit check (per api key if present)
    if api_key:
        rpm = api_key.get("rate_limit_rpm")
        try:
            rpm = int(rpm)
        except Exception:
            rpm = None
        if rpm is None or rpm < 1 or rpm > 6000:
            _log(reqlog, api_key_id, None, "error", {"reset_id": reset_id}, {"error_code": "VALIDATION_ERROR"})
            _save("request_log.json", reqlog)
            return _err("VALIDATION_ERROR", "API key has invalid rate_limit_rpm.")
        window_start = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in reqlog:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                used += 1
        if used >= rpm:
            _log(reqlog, api_key_id, None, "rate_limited", {"reset_id": reset_id}, {"limit_rpm": rpm, "used_in_window": used})
            _save("request_log.json", reqlog)
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit_rpm=rpm, used_in_window=used)

    # Helper: accept common id prefix typo ("tt_reset_" vs "tt_rst_")
    def _normalize_reset_id(rid):
        if not isinstance(rid, str):
            return rid
        if rid.startswith("tt_reset_"):
            return "tt_rst_" + rid[len("tt_reset_") :]
        return rid

    # Determine which reset to roll back
    target_reset = None
    if reset_id is not None:
        rid_norm = _normalize_reset_id(reset_id)
        for r in resets:
            if r.get("id") == reset_id or r.get("id") == rid_norm:
                target_reset = r
                break
        if target_reset is None:
            _log(reqlog, api_key_id, None, "error", {"reset_id": reset_id}, {"error_code": "NOT_FOUND"})
            _save("request_log.json", reqlog)
            return _err("NOT_FOUND", "No session reset found with that id.")
        if target_reset.get("status") != "applied":
            _log(reqlog, api_key_id, target_reset.get("session_id"), "error", {"reset_id": reset_id}, {"error_code": "CONFLICT"})
            _save("request_log.json", reqlog)
            return _err("CONFLICT", "Specified reset is not in status 'applied' and cannot be rolled back.")
    else:
        # Ambient session context: choose the most recent applied reset across all sessions.
        # (With no caller identifier, this is the only consistent way to pick a "current" session.)
        best = None
        best_dt = None
        for r in resets:
            if r.get("status") != "applied":
                continue
            cdt = _parse_dt(r.get("created_at"))
            if cdt is None:
                continue
            if best is None or cdt > best_dt:
                best = r
                best_dt = cdt
        target_reset = best
        if target_reset is None:
            _log(reqlog, api_key_id, None, "error", {"reset_id": None}, {"error_code": "NOT_FOUND"})
            _save("request_log.json", reqlog)
            return _err("NOT_FOUND", "No applicable applied reset exists to roll back.")

    session_id = target_reset.get("session_id")
    if not isinstance(session_id, str) or not session_id:
        _log(reqlog, api_key_id, None, "error", {"reset_id": reset_id}, {"error_code": "VALIDATION_ERROR"})
        _save("request_log.json", reqlog)
        return _err("VALIDATION_ERROR", "Reset row is missing a valid session_id.")

    # Resolve the session; must be non-archived to be in current context
    session = None
    for s in sessions:
        if s.get("id") == session_id:
            session = s
            break
    if session is None:
        _log(reqlog, api_key_id, session_id, "error", {"reset_id": reset_id}, {"error_code": "NOT_FOUND"})
        _save("request_log.json", reqlog)
        return _err("NOT_FOUND", "Reset references a session that does not exist.")
    if session.get("status") == "archived":
        _log(reqlog, api_key_id, session_id, "error", {"reset_id": reset_id}, {"error_code": "UNAUTHORIZED"})
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No active session context for this reset (session is archived).")

    # Lifecycle transition check for reset
    if target_reset.get("status") != "applied":
        _log(reqlog, api_key_id, session_id, "error", {"reset_id": reset_id}, {"error_code": "INVALID_TRANSITION"})
        _save("request_log.json", reqlog)
        return _err("INVALID_TRANSITION", "Reset cannot transition to rolled_back from its current status.")

    # Restore thoughts: rollback means undo the most recent clear operation.
    # This datastore does not track per-thought reset membership; the closest real behavior is:
    # restore all deleted thoughts in the session (soft undelete) ONLY if the session is currently cleared,
    # and then recompute session cached stats to match thoughts after restoration.
    if session.get("status") not in ("cleared", "active"):
        _log(reqlog, api_key_id, session_id, "error", {"reset_id": reset_id}, {"error_code": "CONFLICT"})
        _save("request_log.json", reqlog)
        return _err("CONFLICT", f"Session status '{session.get('status')}' is not eligible for rollback_clear.")

    restored = 0
    for t in thoughts:
        if t.get("session_id") != session_id:
            continue
        if t.get("status") == "deleted":
            # Undelete (even though thoughts lifecycle doesn't include this transition,
            # rollback_clear is a special administrative rollback and is allowed by this tool's contract.)
            t["status"] = "recorded"
            t["deleted_at"] = None
            t["updated_at"] = now
            restored += 1

    # Transition reset applied -> rolled_back
    target_reset["status"] = "rolled_back"
    target_reset["updated_at"] = now

    # Restore session to active and recompute cached stats
    count = 0
    total_chars = 0
    last_dt = None
    last_iso = None
    for t in thoughts:
        if t.get("session_id") != session_id:
            continue
        if t.get("status") == "deleted":
            continue
        count += 1
        tc = t.get("thought_chars")
        if not isinstance(tc, int):
            thtxt = t.get("thought")
            tc = len(thtxt) if isinstance(thtxt, str) else 0
        if tc < 0:
            tc = 0
        total_chars += tc
        cdt = _parse_dt(t.get("created_at"))
        if cdt is not None and (last_dt is None or cdt > last_dt):
            last_dt = cdt
            last_iso = t.get("created_at")

    # Session lifecycle: cleared -> active is allowed; active -> active is idempotent
    if session.get("status") == "cleared":
        session["status"] = "active"
    session["thought_count"] = count
    session["total_chars"] = total_chars
    session["last_thought_at"] = last_iso
    session["updated_at"] = now

    # Persist
    _save("thoughts.json", thoughts)
    _save("session_resets.json", resets)
    _save("sessions.json", sessions)

    _log(
        reqlog,
        api_key_id,
        session_id,
        "success",
        {"reset_id": reset_id},
        {"restored_thoughts": restored, "thought_count": count, "total_chars": total_chars},
    )
    _save("request_log.json", reqlog)

    return {
        "reset": target_reset,
        "session_stats": {
            "session_id": session_id,
            "status": session.get("status"),
            "thought_count": session.get("thought_count"),
            "total_chars": session.get("total_chars"),
            "last_thought_at": session.get("last_thought_at"),
            "updated_at": session.get("updated_at"),
        },
    }

def whoami(api_key=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0152000" if __import__("os").path.isdir("./environment_mix/0152000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dur_ms():
        return int((time.perf_counter() - t0) * 1000)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    api_keys = _load("api_keys.json")
    reqlog = _load("request_log.json")

    # Validate api_key param
    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        reqlog_row = {
            "id": _new_id("req"),
            "api_key_id": None,
            "session_id": None,
            "tool_name": "think",
            "status": "error",
            "request_payload": {"api_key": "<invalid>"},
            "response_meta": {"error_code": "VALIDATION_ERROR"},
            "duration_ms": _dur_ms(),
            "created_at": now,
            "updated_at": now,
        }
        reqlog.append(reqlog_row)
        _save("request_log.json", reqlog)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided.")

    # Authenticate:
    # Contract: never compare to stored hash; accept by matching provided credential to api_keys.id or key_hash
    # (client-visible value or its id). Since plaintext isn't stored, allow id match primarily, and also
    # allow direct key_hash match for stores that use it as visible token.
    key_row = None
    if api_key is not None:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key or k.get("key_hash") == api_key:
                key_row = k
                break
    else:
        # Ambient: pick an active key if any exists; otherwise unauthorized.
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if active:
            # Prefer the one most recently updated
            def _parse_dt(x):
                if not isinstance(x, str):
                    return None
                s = x[:-1] if x.endswith("Z") else x
                try:
                    return datetime.datetime.fromisoformat(s)
                except Exception:
                    return None
            active.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min, r.get("id") or ""), reverse=True)
            key_row = active[0]

    if key_row is None:
        reqlog_row = {
            "id": _new_id("req"),
            "api_key_id": None,
            "session_id": None,
            "tool_name": "think",
            "status": "error",
            "request_payload": {"api_key": "<missing>"} if api_key is None else {"api_key": "<provided>"},
            "response_meta": {"error_code": "UNAUTHORIZED"},
            "duration_ms": _dur_ms(),
            "created_at": now,
            "updated_at": now,
        }
        reqlog.append(reqlog_row)
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No valid API key presented.")

    if key_row.get("status") != "active":
        reqlog_row = {
            "id": _new_id("req"),
            "api_key_id": key_row.get("id"),
            "session_id": None,
            "tool_name": "think",
            "status": "error",
            "request_payload": {"api_key": "<provided>"} if api_key is not None else {},
            "response_meta": {"error_code": "UNAUTHORIZED"},
            "duration_ms": _dur_ms(),
            "created_at": now,
            "updated_at": now,
        }
        reqlog.append(reqlog_row)
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Rate-limit consumption info (do not enforce here; enforcement is on other tools, but show usage)
    # Count requests in last 60s for this key.
    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        s = x[:-1] if x.endswith("Z") else x
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = _parse_dt(now) or datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    key_id = key_row.get("id")

    recent = 0
    for r in reqlog:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is not None and ts >= window_start and ts <= now_dt:
            recent += 1

    limit = key_row.get("rate_limit_rpm")
    remaining = None
    if isinstance(limit, int) and limit >= 0:
        remaining = max(0, limit - recent)

    resp = {
        "api_key": {
            "id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "entitlements": {
            "rate_limit_rpm": key_row.get("rate_limit_rpm"),
            "max_thought_chars": key_row.get("max_thought_chars"),
            "max_session_thoughts": key_row.get("max_session_thoughts"),
        },
        "rate_limit": {
            "window_seconds": 60,
            "requests_in_window": recent,
            "limit": limit,
            "remaining": remaining,
        },
    }

    reqlog_row = {
        "id": _new_id("req"),
        "api_key_id": key_id,
        "session_id": None,
        "tool_name": "think",
        "status": "success",
        "request_payload": {"api_key": "<provided>"} if api_key is not None else {"api_key": "<ambient>"},
        "response_meta": {"requests_in_window": recent, "remaining": remaining},
        "duration_ms": _dur_ms(),
        "created_at": now,
        "updated_at": now,
    }
    reqlog.append(reqlog_row)
    _save("request_log.json", reqlog)

    return resp
